u_z1z2 return_svpwm_4active_optz1z2_scaled(svpwm_4active_2zero_24sector_SV_sequence_t version, float theta, float M, int sector_24, float V_DC_Volts){

	const float theta_min = 0.0f;
	const float theta_max = 2*UZ_PIf/24.0f;

	// check version
    uz_assert(version >= 0 && version < 18);

    float u_z1 = 0;
    float u_z2 = 0;


	// sector
	uz_assert(sector_24 > 0 && sector_24 <= 24);

	// repeats for 3 times per full rotation
	int sector_8 = ((sector_24 - 1) % 8) + 1;

	// angle over one sector
	//float theta_pi_12 = fmodf(theta, (float)M_PI / 12.0f);
	float theta_pi_12 = theta - (sector_24 - 1)* (UZ_PIf / 12.0f);

	if (sector_8 == 1){
		u_z1 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][0], theta_pi_12);
		u_z2 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][1], theta_pi_12);
		u_z1 = u_z1 * M;
		u_z2 = u_z2 * M;
	}
	else if (sector_8 == 2){
		theta_pi_12 = UZ_PIf/12.0f - theta_pi_12;
	    u_z1 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][1], theta_pi_12);
		u_z2 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][0], theta_pi_12);
	    u_z1 = u_z1 * M;
	    u_z2 = u_z2 * M;
	}
	else if (sector_8 == 3){
		u_z1 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][1], theta_pi_12);
		u_z2 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][0], theta_pi_12);
		u_z1 = -(u_z1)* M;
		u_z2 = u_z2 * M;
	}
	else if (sector_8 == 4){
		theta_pi_12 = UZ_PIf/12.0f - theta_pi_12;
		u_z1 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][0], theta_pi_12);
		u_z2 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][1], theta_pi_12);
	    u_z1 = -(u_z1)* M;
	    u_z2 = u_z2 * M;
	}
	else if (sector_8 == 5){
		u_z1 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][0], theta_pi_12);
		u_z2 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][1], theta_pi_12);
		u_z1 = -(u_z1)* M;
		u_z2 = -(u_z2)* M;
	}
	else if (sector_8 == 6){
		theta_pi_12 = UZ_PIf/12.0f - theta_pi_12;
		u_z1 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][1], theta_pi_12);
		u_z2 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][0], theta_pi_12);
	    u_z1 = -(u_z1)* M;
	    u_z2 = -(u_z2)* M;
	}
	else if (sector_8 == 7){
		u_z1 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][1], theta_pi_12);
		u_z2 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][0], theta_pi_12);
		u_z1 = u_z1 * M;
		u_z2 = -(u_z2) * M;
	}
	else {//if (sector_8 == 8)
		theta_pi_12 = UZ_PIf/12.0f - theta_pi_12;
		u_z1 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][0], theta_pi_12);
		u_z2 = uz_interp1_uniform(theta_min, theta_max, 129 , svpwm_4active_optz1z2_scaled_LUT[version][1], theta_pi_12);
		u_z1 = u_z1 * M;
		u_z2 = -(u_z2) * M;
	}

	u_z1 = u_z1 * V_DC_Volts;
	u_z2 = u_z2 * V_DC_Volts;

	return (u_z1z2) {u_z1, u_z2};;
}
